solutions.naive:
class Solution:
    def grayCode(self, n: int) -> list[int]:
        total = 1 << n
        path = [0]
        used = {0}
        def dfs(x):
            if len(path) == total:
                return (path[-1] ^ path[0]).bit_count() == 1 or total == 1
            for bit in range(n):
                y = x ^ (1 << bit)
                if y not in used:
                    used.add(y)
                    path.append(y)
                    if dfs(y):
                        return True
                    path.pop()
                    used.remove(y)
            return False
        dfs(0)
        return path

solutions.better:
class Solution:
    def grayCode(self, n: int) -> list[int]:
        ans = [0]
        for bit in range(n):
            add = 1 << bit
            for x in reversed(ans):
                ans.append(add | x)
        return ans

